  function suggestedPrice(){const price=Number(state.marketSnapshots[state.selectedMarket.id]?.lastPrice);if(!Number.isFinite(price)||price<=0)return'';const raw=price*1.01,power=10**Math.max(-8,Math.floor(Math.log10(raw))-2);return String(Math.ceil(raw/power)*power)}
  function openAlertDialog(){if(!ZychAlertCore.SUPPORTED_EXCHANGES.includes(state.selectedMarket.exchange))return setHistoryStatus('Alerts are not supported on this exchange','error',3500);alertSound.unlock();const market=state.selectedMarket;document.getElementById('alert-market-label').textContent=`${marketLabel(market)} · ${EXCHANGES[market.exchange].label}`;alertForm.reset();alertTypeInputs.forEach(input=>{input.disabled=market.exchange==='coinbase'&&input.value!=='price'||market.exchange==='kraken'&&input.value==='volume';input.title=input.disabled?(market.exchange==='kraken'?'Kraken quote-volume alerts are unavailable; OHLC volume is base-denominated.':'Coinbase currently supports price crossing alerts only.'):'';});alertForm.elements['price-value'].value=suggestedPrice();alertForm.elements['movement-percent'].value='3';alertForm.elements['volume-multiplier'].value='2';alertFormError.textContent='';updateAlertType();alertDialogBackdrop.hidden=false;setTimeout(()=>alertForm.querySelector('input:not([type="radio"]),select')?.focus(),0)}
