  let snapshotController=null,universeController=null;
  function publishQuotes(exchange,rows,requested){
    const markets=(requested||MARKETS).filter(market=>market.exchange===exchange),byId=new Map(rows.map(row=>[row.marketId,row]));
    for(const market of markets){const value=byId.get(market.id),previous=state.marketSnapshots[market.id];if(value){state.marketSnapshots[market.id]={...value,refreshFailed:false,reliability:ZychSnapshotReliability.evaluate(value,exchange)};if(market.id===marketForAsset(market.asset)?.id)updatePulse(market.asset,value);}else if(previous)state.marketSnapshots[market.id]={...previous,refreshFailed:true};}
    renderMarket();renderWatchlist();renderMarketsDashboard();if(!searchResults.hidden)drawSearch();
  }
  async function refreshSnapshots(){
    if(!catalogLoader)return;
    const browseAssets=[state.selectedMarket.asset,'BTC','ETH','SOL'],savedMarkets=resolvedWatchlistMarkets().map(entry=>entry.market),requested=[...new Map(savedMarkets.concat(MARKETS.filter(market=>market.exchange===state.activeExchange),browseAssets.map(asset=>marketForAsset(asset)).filter(Boolean)).map(market=>[market.id,market])).values()];
    await Promise.all(Object.entries(Object.groupBy(requested,market=>market.exchange)).map(([exchange,markets])=>catalogLoader.refresh(exchange,markets)));
  }
  function updateCatalogState(){
    const statuses=Object.values(catalogLoader.states);universeStatus=statuses.some(state=>state.catalog==='loading')?'loading':statuses.some(state=>state.catalog==='ready')?'ready':'error';
    state.loadingState.universe=universeStatus==='loading';state.errorState.universe=universeStatus==='error'?'Market universe unavailable':null;
    document.documentElement.dataset.exchanges=Object.entries(catalogLoader.states).filter(([,value])=>value.catalog==='ready').map(([exchange])=>exchange).join(',');
    renderWatchlist();renderMarketsDashboard();if(!searchResults.hidden)drawSearch();
  }
